def copy_random_list_hash(head):
    if not head:
        return None
    mapping = {}
    cur = head
    while cur:
        mapping[cur] = type(cur)(cur.val)
        cur = cur.next
    cur = head
    while cur:
        mapping[cur].next = mapping.get(cur.next)
        mapping[cur].random = mapping.get(cur.random)
        cur = cur.next
    return mapping[head]
